CATEGORY_TARGETS = {"general_knowledge": 50, "reasoning": 30, "coding": 20,
                   "long_context": 20, "multimodal_document": 10, "multimodal_image": 10}

def validate_suite():
    ids = [item["id"] for item in CASES]
    counts = {key: sum(1 for item in CASES if item["category"] == key) for key in CATEGORY_TARGETS}
    return {"total": len(CASES), "unique_ids": len(set(ids)), "category_counts": counts,
            "valid": len(ids) == len(set(ids)) and counts == CATEGORY_TARGETS and len(ids) == 140}
